steps.command:
mkdir -p /srv/upload && cat > /srv/upload/srv.pl <<'PERLEOF'
use strict; use warnings;
use IO::Socket::INET;
use File::Temp qw(tempfile);
my $srv = IO::Socket::INET->new(LocalAddr=>'127.0.0.1', LocalPort=>8082,
                                Listen=>5, ReuseAddr=>1, Proto=>'tcp') or die "bind: $!";
my $pid = fork(); die "fork: $!" unless defined $pid;
if (!$pid) {
    for (1..3) {
        my $c = $srv->accept() or next;
        my $len = 0;
        while (my $line = <$c>) {
            $line =~ s/\r?\n$//;
            last if $line eq '';
            $len = $1 if $line =~ /^Content-Length:\s*(\d+)/i;
        }
        my $body = '';
        read($c, $body, $len) if $len;
        my ($fh, $path) = tempfile("req-XXXXXX", DIR => "/tmp");
        print $fh $body; close $fh;
        my $size = -s $path;
        unlink $path;
        print $c "HTTP/1.0 200 OK\r\nContent-Length: " . length($size) . "\r\n\r\n$size";
        close $c;
    }
    exit 0;
}
for my $i (0..2) {
    my $c = IO::Socket::INET->new(PeerAddr=>'127.0.0.1', PeerPort=>8082, Proto=>'tcp')
        or die "connect: $!";
    my $body = "payload-$i";
    print $c "POST /upload HTTP/1.0\r\nContent-Length: " . length($body) . "\r\n\r\n$body";
    my @resp = <$c>;
    print "stored bytes $resp[-1]\n";
    close $c;
}
waitpid($pid, 0);
close $srv;
print "server closed\n";
PERLEOF
perl -c /srv/upload/srv.pl
